import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import { DEFAULT_CANDIDATE, assess, overlapHours } from "./eligibility";
import type { Posting } from "./feed";

// Generated by `job-radar eval regions --write-web-fixture`; pytest checks it is current.
const cases = JSON.parse(
  readFileSync(new URL("./__fixtures__/region-traps.json", import.meta.url), "utf-8"),
) as { id: string; expected: string; posting: Partial<Posting> }[];

// The feed carries the region map; the sample feed is generated by the same exporter.
const feed = JSON.parse(
  readFileSync(new URL("../public/sample-feed.json", import.meta.url), "utf-8"),
) as { regions: Record<string, string[]> };

describe("region trap set (same cases as the Python rule eval)", () => {
  it.each(cases.map((c) => [c.id, c] as const))("%s", (_id, c) => {
    const verdict = assess(c.posting as Posting, DEFAULT_CANDIDATE, feed.regions);
    expect(verdict.label).toBe(c.expected);
  });
});

describe("overlapHours", () => {
  it("matches the Python rule for US Pacific and CET", () => {
    expect(overlapHours(DEFAULT_CANDIDATE, -8)).toBe(1);
    expect(overlapHours(DEFAULT_CANDIDATE, 1)).toBe(7);
    expect(overlapHours(DEFAULT_CANDIDATE, 8)).toBe(8);
  });
});
